"""Small YAML subset reader for Taskfiles (stdlib only)."""
import ast
import re


def _scalar(s):
    s = s.strip()
    if not s:
        return None
    if s in ('null', 'Null', 'NULL', '~'):
        return None
    if s.lower() in ('true', 'false'):
        return s.lower() == 'true'
    if s.startswith('[') and s.endswith(']'):
        body = s[1:-1].strip()
        return [] if not body else [_scalar(x) for x in _split(body)]
    if s.startswith('{') and s.endswith('}'):
        body = s[1:-1].strip()
        out = {}
        for x in _split(body):
            if ':' in x:
                k, v = x.split(':', 1); out[str(_scalar(k))] = _scalar(v)
        return out
    if s[0:1] in ('"', "'"):
        try:
            return ast.literal_eval(s) if s[0] == '"' else s[1:-1].replace("''", "'")
        except Exception:
            return s[1:-1]
    if re.fullmatch(r'[-+]?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?', s):
        try: return int(s) if '.' not in s else float(s)
        except ValueError: pass
    return s


def _split(text):
    parts=[]; start=0; quote=None; depth=0
    for i,ch in enumerate(text):
        if quote:
            if ch == quote and (i == 0 or text[i-1] != '\\'): quote=None
        elif ch in ('"', "'"): quote=ch
        elif ch in '[{(': depth += 1
        elif ch in ']})': depth -= 1
        elif ch == ',' and depth == 0:
            parts.append(text[start:i].strip()); start=i+1
    parts.append(text[start:].strip())
    return parts


def _colon(line):
    quote=None; depth=0
    for i,ch in enumerate(line):
        if quote:
            if ch == quote and (i == 0 or line[i-1] != '\\'): quote=None
        elif ch in ('"', "'"): quote=ch
        elif ch in '[{(': depth += 1
        elif ch in ']})': depth -= 1
        elif ch == ':' and depth == 0 and (i+1 == len(line) or line[i+1].isspace()):
            return i
    return -1


def loads(text):
    lines=[]; raw=text.splitlines(); i=0
    while i < len(raw):
        line=raw[i]
        if not line.strip() or line.lstrip().startswith('#') or line.strip() in ('---','...'):
            i+=1; continue
        indent=len(line)-len(line.lstrip(' ')); s=line[indent:]
        # Literal/folded block scalar.
        c=_colon(s)
        if c >= 0:
            val=s[c+1:].strip()
            if val in ('|','|-','|+','>','>-','>+'):
                block=[]; j=i+1
                while j<len(raw) and (not raw[j].strip() or len(raw[j])-len(raw[j].lstrip(' '))>indent):
                    block.append(raw[j][min(len(raw[j])-len(raw[j].lstrip(' ')),indent+1):] if raw[j].strip() else '')
                    j+=1
                lines.append((indent,s[:c].strip(), ('\n' if val.startswith('|') else ' ').join(block).rstrip('\n'))); i=j; continue
        # Remove comments outside quotes, only when preceded by whitespace.
        quote=None; cut=len(s)
        for k,ch in enumerate(s):
            if quote:
                if ch==quote and (k==0 or s[k-1]!='\\'): quote=None
            elif ch in ('"',"'"): quote=ch
            elif ch=='#' and (k==0 or s[k-1].isspace()): cut=k; break
        s=s[:cut].rstrip()
        if s: lines.append((indent,s,None))
        i+=1
    def parse(pos, indent):
        if pos>=len(lines): return None,pos
        isseq=lines[pos][1].startswith('- ' ) or lines[pos][1]=='-'
        obj=[] if isseq else {}
        while pos<len(lines) and lines[pos][0]==indent:
            _,s,block=lines[pos]
            if isseq:
                if not (s.startswith('- ') or s=='-'): break
                item=s[1:].strip(); pos+=1
                if not item:
                    if pos<len(lines) and lines[pos][0]>indent: val,pos=parse(pos,lines[pos][0])
                    else: val=None
                    obj.append(val); continue
                c=_colon(item)
                if c>=0:
                    key=str(_scalar(item[:c])); v=item[c+1:].strip()
                    d={}
                    if v: d[key]=_scalar(v)
                    elif block is not None: d[key]=block
                    elif pos<len(lines) and lines[pos][0]>indent+1: d[key],pos=parse(pos,lines[pos][0])
                    else: d[key]=None
                    if pos<len(lines) and lines[pos][0]>indent:
                        extra,pos=parse(pos,lines[pos][0])
                        if isinstance(extra,dict): d.update(extra)
                    obj.append(d)
                else: obj.append(_scalar(item))
            else:
                c=_colon(s)
                if c<0: pos+=1; continue
                key=str(_scalar(s[:c])); v=s[c+1:].strip(); pos+=1
                if block is not None: obj[key]=block
                elif v: obj[key]=_scalar(v)
                elif pos<len(lines) and lines[pos][0]>indent:
                    obj[key],pos=parse(pos,lines[pos][0])
                else: obj[key]=None
        return obj,pos
    return parse(0,lines[0][0])[0] if lines else {}
