import os, re, shlex, subprocess, sys


def render(s, values):
    if not isinstance(s, str):
        return s
    # Task's common Go-template interpolation forms.
    def repl(m):
        key=m.group(1).strip()
        if key.startswith('.'): key=key[1:]
        if key.startswith('$'): key=key[1:]
        v=values.get(key, '')
        if isinstance(v, bool): return str(v).lower()
        if isinstance(v, (list,dict)): return str(v)
        return str(v)
    return re.sub(r'{{\s*([.$][\w.-]+)\s*}}', repl, s)


def run_tasks(taskfile, names, *, directory=None, dry=False, silent=False, verbose=False,
              force=False, cli_args=None, env=None, failfast=False, exit_code=False):
    """Run named tasks from a decoded Taskfile mapping; return process status."""
    tasks=taskfile.get('tasks') or {}
    base=os.path.abspath(directory or os.getcwd())
    global_vars=dict(taskfile.get('vars') or {})
    executed=set(); active=set(); failed=0
    def run(name, alias=None):
        nonlocal failed
        if name in active:
            print(f'task: task dependency cycle detected: {name}', file=sys.stderr); failed=1; return
        if name in executed: return
        t=tasks.get(name)
        if t is None:
            print(f'task: Task "{name}" does not exist', file=sys.stderr); failed=1; return
        if isinstance(t,str): t={'cmds':[t]}
        elif isinstance(t,list): t={'cmds':t}
        if not isinstance(t,dict): t={}
        active.add(name)
        for dep in reversed(t.get('deps',[]) or []):
            if isinstance(dep,dict): run(dep.get('task',''))
            else: run(str(dep))
        if failed and failfast:
            active.remove(name); return
        vals=dict(global_vars); vals.update(t.get('vars') or {})
        vals.update({'TASK':name,'ALIAS':alias or name,'CLI_ARGS':' '.join(shlex.quote(x) for x in (cli_args or [])),'CLI_ARGS_LIST':cli_args or [],'CLI_FORCE':force,'CLI_SILENT':silent,'CLI_VERBOSE':verbose})
        req=(t.get('requires') or {}).get('vars',[]) if isinstance(t.get('requires'),dict) else []
        missing=[str(k) for k in req if k not in vals or vals.get(k) in (None,'')]
        if missing:
            print(f'task: Task "{name}" cancelled because it is missing required variables: {", ".join(missing)}',file=sys.stderr)
            failed=206; active.remove(name); return
        # Resolve variable references and simple nested templates.
        for _ in range(5):
            before=dict(vals)
            for k,v in list(vals.items()):
                if isinstance(v,str): vals[k]=render(v,vals)
            if before==vals: break
        cmds=t.get('cmds',[]) or []
        if isinstance(cmds,(str,dict)): cmds=[cmds]
        for c in cmds:
            if failed: break
            if isinstance(c,dict):
                if c.get('task'): run(str(c['task'])); continue
                cmd=c.get('cmd','')
                c_silent=bool(c.get('silent',False))
                ignore_error=bool(c.get('ignore_error',False))
                if c.get('for'):
                    for item in vals.get(str(c['for']).lstrip('.'),[]):
                        vv=dict(vals); vv[str(c['for']).split()[-1].lstrip('$')]=item
                        execute(render(cmd,vv),name,c_silent,bool(c.get('ignore_error',False)))
                    continue
            else: cmd=c; c_silent=False; ignore_error=False
            execute(render(str(cmd), vals),name,c_silent,ignore_error)
        active.remove(name); executed.add(name)
    def execute(cmd,name,cmd_silent=False,ignore_error=False):
        nonlocal failed
        if not cmd or cmd_silent: pass
        elif not silent: print(f'task: [{name}] {cmd}',flush=True)
        if dry: return
        if not cmd: return
        try:
            p=subprocess.run(cmd,shell=True,cwd=base,env={**os.environ,**(env or {})})
            if p.returncode and not ignore_error:
                print(f'task: Failed to run task \"{name}\": exit status {p.returncode}',file=sys.stderr)
                failed=p.returncode if exit_code else 201
        except Exception: failed=1
    for n in names:
        if failed: break
        run(n)
    return failed
