#!/usr/bin/env python3
import json, os, sys, difflib
from pathlib import Path
from yamlmini import loads
from execution import run_tasks

VERSION='3.51.1'
HELP='''Usage: task [flags...] [task...]\n\nRuns the specified task(s). Falls back to the "default" task if no task name\nwas specified, or lists all tasks if an unknown task name was specified.\n\nOptions:\n  -c, --color                       Colored output. Enabled by default.\n      --completion string           Generates shell completion script.\n  -C, --concurrency int             Limit number of tasks to run concurrently.\n  -d, --dir string                  Sets the directory in which Task will execute and look for a Taskfile.\n      --disable-fuzzy               Disables fuzzy matching for task names.\n  -n, --dry                         Compiles and prints tasks without executing them.\n  -x, --exit-code                   Pass-through the exit code of the task command.\n  -F, --failfast                    When running tasks in parallel, stop all tasks if one fails.\n  -f, --force                       Forces execution even when the task is up-to-date.\n  -g, --global                      Runs global Taskfile, from $HOME/{T,t}askfile.{yml,yaml}.\n  -h, --help                        Shows Task usage.\n  -i, --init                        Creates a new Taskfile.yml in the current folder.\n      --insecure                    Forces Task to download Taskfiles over insecure connections.\n      --interactive                 Prompt for missing required variables.\n  -I, --interval duration           Interval to watch for changes.\n  -j, --json                        Formats task list as JSON.\n  -l, --list                        Lists tasks with description of current Taskfile.\n  -a, --list-all                    Lists tasks with or without a description.\n      --nested                      Nest namespaces when listing tasks as JSON.\n      --no-status                   Ignore status when listing tasks as JSON.\n  -o, --output string               Sets output style: [interleaved|group|prefixed].\n  -p, --parallel                    Executes tasks provided on command line in parallel.\n  -s, --silent                      Disables echoing.\n      --sort string                 Changes task order. [default|alphanumeric|none].\n  -t, --taskfile string             Choose which Taskfile to run. Defaults to "Taskfile.yml".\n  -v, --verbose                     Enables verbose mode.\n      --version                     Shows version.\n  -w, --watch                       Enables watch of the given task.\n  -y, --yes                         Assume "yes" as answer to all prompts.\n'''
INIT='''# yaml-language-server: $schema=https://taskfile.dev/schema.json\n\nversion: '3'\n\nvars:\n  GREETING: Hello, world!\n\ntasks:\n  default:\n    desc: Print a greeting message\n    cmds:\n      - echo "{{.GREETING}}"\n    silent: true\n'''

def die(msg, code=100):
    print('task: '+msg,file=sys.stderr); return code

def find_file(directory, explicit=None):
    if explicit:
        p=Path(explicit)
        if not p.is_absolute(): p=Path(directory)/p
        return p.resolve() if p.is_file() else None
    names=('Taskfile.yml','Taskfile.yaml','taskfile.yml','taskfile.yaml')
    d=Path(directory).resolve()
    for cur in [d,*d.parents]:
        for n in names:
            p=cur/n
            if p.is_file(): return p
    return None

def task_desc(t):
    return str(t.get('desc') or '') if isinstance(t,dict) else ''
def task_aliases(t):
    a=t.get('aliases',[]) if isinstance(t,dict) else []
    return [str(x) for x in (a or [])]
def list_tasks(root, all_tasks=False, sort='default', silent=False, json_mode=False, path='', no_status=False, nested=False):
    tasks=root.get('tasks') or {}
    names=list(tasks)
    if not all_tasks: names=[n for n in names if task_desc(tasks[n]) and not (isinstance(tasks[n],dict) and tasks[n].get('internal'))]
    if sort!='none': names.sort(key=lambda n:n.lower())
    if json_mode:
        def item(n):
            t=tasks[n] if isinstance(tasks[n],dict) else {}
            row={'name':n,'task':n,'desc':task_desc(tasks[n]),'summary':str(t.get('summary') or ''),'aliases':task_aliases(tasks[n])}
            if not no_status: row['up_to_date']=False
            row['location']={'line':0,'column':3,'taskfile':str(path)}
            return row
        obj={'tasks':[],'location':str(path)}
        for n in names:
            if nested and ':' in n:
                ns,rest=n.split(':',1)
                branch=obj.setdefault('namespaces',{}).setdefault(ns,{'tasks':[]})
                branch['tasks'].append(item(n))
            else: obj['tasks'].append(item(n))
        print(json.dumps(obj,indent=2,ensure_ascii=False)); return
    if silent:
        for n in names:
            print(n)
            for a in task_aliases(tasks[n]): print(a)
        return
    print('task: Available tasks for this project:')
    width=max([len(n) for n in names] or [0])
    for n in names:
        alias=task_aliases(tasks[n]); suffix=f" (aliases: {', '.join(alias)})" if alias else ''
        print(f"* {n+':':<{width+2}}  {task_desc(tasks[n])}{suffix}")

def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    if '--' in argv:
        ix=argv.index('--'); cli_args=argv[ix+1:]; argv=argv[:ix]
    else: cli_args=[]
    if '-h' in argv or '--help' in argv: print(HELP); return 0
    if '--version' in argv: print(VERSION); return 0
    if '--experiments' in argv:
        print('* GENTLE_FORCE:     off\n* REMOTE_TASKFILES: off\n* ENV_PRECEDENCE:   off'); return 0
